:root {
    --green: #082313;
    --green2: #0e351b;
    --gold: #e7bd61;
    --cream: #f5f0e3;
    --ink: #152017
}

* {
    box-sizing: border-box
}

html {
    scroll-behavior: smooth
}

body {
    margin: 0;
    font-family: Arial, Helvetica, sans-serif;
    color: var(--ink);
    background: var(--cream)
}

a {
    text-decoration: none;
    color: inherit
}

header {
    position: sticky;
    top: 0;
    z-index: 50;
    background: #050505;
    color: #fff;
    border-bottom: 1px solid rgba(231, 189, 97, .35);
    height: 82px;
    display: flex;
    align-items: center;
    padding: 0 4.5%;
    gap: 20px
}

.brand {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 405px;
    flex-shrink: 0
}

.leaf {
    font-size: 46px;
    color: var(--gold)
}

.brand h1 {
    font: 700 30px Georgia, serif;
    color: var(--gold);
    margin: 0
}

.brand small {
    display: block;
    color: #fff;
    font-size: 12px;
    letter-spacing: 1px
}

nav {
    margin-left: auto;
    display: flex;
    gap: 27px;
    font-size: 13px
}

nav a:hover {
    color: var(--gold)
}

.active {
    color: var(--gold);
    border-bottom: 2px solid var(--gold);
    padding-bottom: 9px
}

.hero {
    min-height: 500px;
    color: #fff;
    padding: 75px 6%;
    display: flex;
    align-items: center;
    background: linear-gradient(90deg, rgba(2, 13, 6, .95), rgba(2, 13, 6, .62) 43%, rgba(2, 13, 6, .1)), url("data:image/png;base64,") center 7%/cover
}

.hero-copy {
    max-width: 560px
}

.eyebrow {
    letter-spacing: 3px;
    font-size: 13px
}

.hero h2 {
    font: 700 54px/1.02 Georgia, serif;
    margin: 14px 0
}

.hero h2 span {
    color: var(--gold)
}

.hero p {
    font-size: 16px;
    line-height: 1.7;
    max-width: 510px;
    color: #eee
}

.btn {
    display: inline-block;
    background: var(--gold);
    border: 0;
    border-radius: 30px;
    padding: 15px 25px;
    font-weight: 700;
    cursor: pointer;
    color: #111
}

.features {
    background: #07140b;
    color: #fff;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    padding: 25px 6%;
    text-align: center
}

.feature {
    padding: 8px;
    border-right: 1px solid #806a35
}

.feature:last-child {
    border: 0
}

.icon {
    font-size: 28px;
    color: var(--gold)
}

.feature b {
    display: block;
    margin-top: 7px
}

section {
    padding: 55px 6%
}

.title h2 {
    font: 700 34px Georgia, serif;
    margin: 0 0 5px
}

.title p {
    margin: 0;
    color: #555
}

.cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 17px;
    margin-top: 25px
}

.card {
    background: #faf8f0;
    border: 1px solid #d0ccbd;
    border-radius: 14px;
    overflow: hidden
}

.card-photo {
    height: 170px;
    background: #ddd center/cover no-repeat
}

.card:nth-child(1) .card-photo {
    background-position: 45% 38%
}

.card:nth-child(2) .card-photo {
    background-position: 52% 35%
}

.card:nth-child(3) .card-photo {
    background-position: 60% 38%
}

.card:nth-child(4) .card-photo {
    background-position: 70% 38%
}

.card-body {
    padding: 18px 20px 22px
}

.card h3 {
    font: 700 21px Georgia, serif;
    margin: 0 0 8px
}

.card p {
    font-size: 14px;
    line-height: 1.55;
    color: #555;
    min-height: 65px
}

.learn {
    color: #174723;
    font-weight: 700;
    font-size: 13px
}

.about {
    background: #06180b;
    color: #fff;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 40px;
    align-items: center
}

.about h2 {
    font: 700 31px Georgia, serif;
    color: var(--gold)
}

.about p {
    line-height: 1.65;
    color: #ddd
}

.about-photo {
    height: 290px;
    border-radius: 18px;
    background: linear-gradient(90deg, rgba(5, 19, 9, .1), rgba(5, 19, 9, .2)), url("data:image/png;base64,") center 66%/cover
}

.why {
    text-align: center;
    background: #f8f4e9
}

.why h2 {
    font: 700 31px Georgia, serif
}

.why-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    margin-top: 25px
}

.why-item {
    padding: 15px;
    border-right: 1px solid #d5d0c0;
    font-weight: 700
}

.why-item:last-child {
    border: 0
}

.why-item span {
    display: block;
    font-size: 30px;
    color: #246232;
    margin-bottom: 8px
}

.contact {
    background: linear-gradient(90deg, rgba(4, 19, 8, .94), rgba(4, 19, 8, .9)), url("data:image/png;base64,") center 92%/cover;
    color: #fff;
    display: grid;
    grid-template-columns: .9fr 1.1fr;
    gap: 55px;
    align-items: center
}

.contact h2 {
    font: 700 34px Georgia, serif;
    color: #fff
}

.contact p {
    color: #ddd;
    line-height: 1.6
}

.since {
    margin-top: 28px;
    border-top: 1px solid rgba(231, 189, 97, .55);
    padding-top: 18px;
    color: var(--gold);
    font-weight: 700;
    font-size: 19px
}

.form {
    border: 1px solid var(--gold);
    border-radius: 18px;
    padding: 28px;
    background: rgba(4, 22, 9, .68);
    box-shadow: 0 18px 50px rgba(0, 0, 0, .25)
}

.form h3 {
    font: 700 28px Georgia, serif;
    margin: 0 0 5px
}

.form p {
    font-size: 13px;
    margin-bottom: 20px
}

.field {
    margin: 13px 0
}

.field input {
    width: 100%;
    height: 57px;
    border-radius: 11px;
    border: 1px solid #ddd;
    background: #fff;
    color: #111;
    padding: 0 17px;
    font-size: 16px;
    outline: 0
}

.field input:focus {
    border-color: var(--gold)
}

.submit {
    width: 100%;
    height: 55px;
    margin-top: 5px;
    background: var(--gold);
    border: 0;
    border-radius: 11px;
    font-size: 16px;
    font-weight: 700;
    cursor: pointer
}

.safe {
    font-size: 11px;
    text-align: center;
    color: #ddd;
    margin: 12px 0 0
}

footer {
    background: #030a05;
    color: #aaa;
    text-align: center;
    padding: 18px;
    font-size: 12px
}

.toast {
    display: none;
    position: fixed;
    right: 22px;
    bottom: 22px;
    background: var(--gold);
    color: #111;
    padding: 14px 20px;
    border-radius: 10px;
    font-weight: 700;
    z-index: 100
}

@media(max-width:900px) {
    header {
        height: auto;
        flex-wrap: wrap;
        padding: 15px 5%
    }

    .brand {
        min-width: 0
    }

    nav {
        width: 100%;
        overflow: auto;
        padding-bottom: 4px
    }

    .hero {
        min-height: 560px
    }

    .cards {
        grid-template-columns: 1fr 1fr
    }

    .features,
    .why-grid {
        grid-template-columns: 1fr 1fr;
        row-gap: 20px
    }

    .about,
    .contact {
        grid-template-columns: 1fr
    }
}

@media(max-width:560px) {
    .hero h2 {
        font-size: 39px
    }

    .cards,
    .features,
    .why-grid {
        grid-template-columns: 1fr
    }

    .feature,
    .why-item {
        border-right: 0;
        border-bottom: 1px solid #806a35
    }

    .contact {
        padding-top: 45px
    }
}

/* Requested visual corrections */
.brand-logo {
    display: block;
    width: 405px;
    height: auto;
    max-height: 70px;
    object-fit: contain;
    object-position: left center
}

.enquiry-highlight {
    padding: 42px 6%;
    background: linear-gradient(135deg, #0a2a14, #123d1f);
    color: #fff
}

.enquiry-inner {
    max-width: 1180px;
    margin: auto;
    display: grid;
    grid-template-columns: 1fr 1.65fr;
    gap: 34px;
    align-items: center;
    border: 2px solid var(--gold);
    border-radius: 22px;
    padding: 28px 30px;
    box-shadow: 0 0 0 5px rgba(231, 189, 97, .08), 0 18px 45px rgba(0, 0, 0, .22)
}

.enquiry-kicker {
    display: inline-block;
    color: var(--gold);
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 2px;
    margin-bottom: 8px
}

.enquiry-copy h2 {
    font: 700 30px Georgia, serif;
    margin: 0 0 10px
}

.enquiry-copy p {
    color: #e6eadf;
    line-height: 1.6;
    margin: 0;
    max-width: 420px
}

.enquiry-form {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 13px 14px
}

.enquiry-form .field {
    display: flex;
    flex-direction: column;
    gap: 6px
}

.enquiry-form label {
    font-size: 12px;
    color: #f3d88f;
    font-weight: 700
}

.enquiry-form input {
    width: 100%;
    padding: 13px 14px;
    border: 1px solid rgba(231, 189, 97, .45);
    border-radius: 10px;
    background: #f8f5eb;
    color: #172018;
    outline: none
}

.enquiry-form input:focus {
    border-color: var(--gold);
    box-shadow: 0 0 0 3px rgba(231, 189, 97, .15)
}

.enquiry-form .submit {
    grid-column: 1/-1;
    width: 100%;
    padding: 14px 18px;
    border: 0;
    border-radius: 10px;
    background: var(--gold);
    color: #111;
    font-weight: 800;
    cursor: pointer
}

.enquiry-form .safe {
    grid-column: 1/-1;
    text-align: center;
    color: #ddd;
    font-size: 12px
}

.about-photo {
    background-position: center;
    background-size: cover;
    background-repeat: no-repeat
}

@media(max-width:900px) {
    .enquiry-inner {
        grid-template-columns: 1fr
    }

    .enquiry-form {
        grid-template-columns: 1fr 1fr
    }
}

@media(max-width:900px) {
    header {
        padding: 0 3%;
    }

    .brand {
        min-width: 0
    }

    .brand-logo {
        width: 330px
    }

    nav {
        gap: 16px;
        font-size: 12px
    }
}

@media(max-width:560px) {
    .brand-logo {
        width: 205px
    }

    .enquiry-inner {
        padding: 22px 18px
    }

    .enquiry-form {
        grid-template-columns: 1fr
    }

    .enquiry-form .submit,
    .enquiry-form .safe {
        grid-column: auto
    }
}

footer .footer-logo {
    display: block;
    width: 245px;
    max-width: 80%;
    margin: 0 auto 10px;
    height: auto
}

/* HD treatment image presentation */
.card-photo {
    image-rendering: auto;
    background-size: cover;
    filter: saturate(1.03) contrast(1.02);
}

/* Floating call button */
.floating-call {
    position: fixed;
    right: 22px;
    bottom: 22px;
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #19a84a;
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    text-decoration: none;
    z-index: 9999;
    box-shadow: 0 10px 28px rgba(0, 0, 0, .30);
    border: 3px solid #fff;
    font-size: 29px;
    transition: transform .2s ease, box-shadow .2s ease;
}

.floating-call:hover {
    transform: scale(1.08);
    box-shadow: 0 14px 32px rgba(0, 0, 0, .38);
}

.floating-call span {
    font-size: 11px;
    font-weight: 800;
    position: absolute;
    bottom: -20px;
    white-space: nowrap;
    background: #fff;
    color: #17632e;
    padding: 3px 7px;
    border-radius: 8px;
    box-shadow: 0 3px 10px rgba(0, 0, 0, .15);
}

.footer-contact {
    margin-top: 12px;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 9px;
    color: #e7bd61;
    font-size: 14px;
}

.footer-contact a {
    color: #e7bd61;
    font-weight: 700;
}

.email-icon {
    width: 20px;
    height: 20px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1.5px solid #e7bd61;
    border-radius: 4px;
    font-size: 12px;
}

@media(max-width:560px) {
    .floating-call {
        right: 16px;
        bottom: 16px;
        width: 58px;
        height: 58px;
        font-size: 26px
    }

    .floating-call span {
        display: none
    }

    .footer-contact {
        font-size: 13px;
    }
}

/* About rating */
.about-copy {
    min-width: 0
}

.about-rating {
    min-height: 230px;
    border: 1px solid rgba(231, 189, 97, .55);
    border-radius: 20px;
    background: linear-gradient(145deg, rgba(231, 189, 97, .10), rgba(13, 55, 25, .48));
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 28px;
    box-shadow: 0 18px 45px rgba(0, 0, 0, .20);
    position: relative;
    overflow: hidden
}

.about-rating::before {
    content: "";
    position: absolute;
    width: 180px;
    height: 180px;
    border-radius: 50%;
    background: rgba(231, 189, 97, .10);
    filter: blur(18px);
    top: -90px;
    right: -50px
}

.rating-stars {
    position: relative;
    color: #e7bd61;
    font-size: 34px;
    letter-spacing: 4px;
    line-height: 1;
    margin-bottom: 10px;
    text-shadow: 0 2px 12px rgba(231, 189, 97, .30)
}

.rating-score {
    position: relative;
    color: #fff;
    font: 700 42px Georgia, serif;
    line-height: 1
}

.rating-score span {
    font-size: 20px;
    color: #ddd;
    font-family: Arial, sans-serif;
    margin-left: 2px
}

.rating-label {
    position: relative;
    color: #e7bd61;
    font-weight: 800;
    font-size: 15px;
    margin-top: 10px
}

.rating-note {
    position: relative;
    color: #ddd;
    font-size: 12px;
    margin-top: 7px
}

/* Contact form shown by the Contact navigation item */
.contact {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 40px;
    align-items: center
}

.contact-copy {
    min-width: 0
}

.contact-form {
    border: 1px solid var(--gold);
    border-radius: 18px;
    padding: 28px;
    background: rgba(4, 22, 9, .76);
    box-shadow: 0 18px 50px rgba(0, 0, 0, .28)
}

.contact-form h3 {
    font: 700 28px Georgia, serif;
    margin: 0 0 5px;
    color: #fff
}

.contact-form>p {
    font-size: 13px;
    margin-bottom: 20px;
    color: #ddd
}

.contact-fields {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0 16px
}

.contact-form .field {
    margin: 10px 0
}

.contact-form .field label {
    display: block;
    color: #e7bd61;
    font-size: 12px;
    font-weight: 700;
    margin-bottom: 6px
}

.contact-form .field input {
    box-sizing: border-box
}

.contact-form .submit {
    grid-column: 1/-1
}

.contact-form .safe {
    grid-column: 1/-1
}

/* Moving green light behind the call button */
.floating-call {
    isolation: isolate;
    overflow: visible
}

.floating-call::after {
    content: "";
    position: absolute;
    inset: -22px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(42, 220, 96, .68) 0%, rgba(25, 168, 74, .34) 32%, rgba(25, 168, 74, .08) 58%, transparent 73%);
    filter: blur(7px);
    z-index: -1;
    animation: callGreenGlow 2.4s ease-in-out infinite;
    pointer-events: none
}

.floating-call svg,
.floating-call span {
    position: relative;
    z-index: 2
}

@keyframes callGreenGlow {

    0%,
    100% {
        transform: scale(.78);
        opacity: .35;
        filter: blur(8px)
    }

    45% {
        transform: scale(1.08);
        opacity: .88;
        filter: blur(4px)
    }

    70% {
        transform: scale(.92);
        opacity: .55;
        filter: blur(7px)
    }
}

@media(max-width:900px) {
    .contact {
        grid-template-columns: 1fr
    }

    .about-rating {
        min-height: 190px
    }

    .contact-fields {
        grid-template-columns: 1fr 1fr
    }
}

@media(max-width:560px) {
    .contact-fields {
        grid-template-columns: 1fr
    }

    .contact-form {
        padding: 22px 18px
    }

    .rating-stars {
        font-size: 29px
    }

    .rating-score {
        font-size: 36px
    }
}

/* Green phone call button with a gentle vibration/pulse effect */
.floating-call {
    background: #19a84a;
    animation: callVibrate 1.8s ease-in-out infinite;
}

.floating-call::before {
    content: "";
    position: absolute;
    inset: -7px;
    border: 2px solid rgba(25, 168, 74, .45);
    border-radius: 50%;
    animation: callPulse 1.8s ease-out infinite;
    pointer-events: none;
}

.call-icon {
    width: 30px;
    height: 30px;
    fill: #fff;
    display: block;
    transform: rotate(-8deg);
}

@keyframes callVibrate {

    0%,
    72%,
    100% {
        transform: translateX(0) rotate(0)
    }

    74% {
        transform: translateX(-1px) rotate(-4deg)
    }

    76% {
        transform: translateX(2px) rotate(4deg)
    }

    78% {
        transform: translateX(-2px) rotate(-4deg)
    }

    80% {
        transform: translateX(1px) rotate(3deg)
    }

    82% {
        transform: translateX(0) rotate(0)
    }
}

@keyframes callPulse {
    0% {
        transform: scale(.82);
        opacity: .75
    }

    70%,
    100% {
        transform: scale(1.18);
        opacity: 0
    }
}

@media(prefers-reduced-motion:reduce) {

    .floating-call,
    .floating-call::before {
        animation: none
    }
}